SELECT COUNT(*)
FROM erp_payment_bill
WHERE student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
  AND bill_type = #{billType}
  AND status IN ('issued', 'approved', 'partial');

SELECT COUNT(*) as count,
payment_key AS paymnetKey,
student_id AS studentId,
bill_id AS billId
FROM erp_payment_bill
WHERE student_id = #{studentId}
  AND payment_key = #{paymentKey}
  AND yy = #{yy}
  AND mm = #{mm}
  AND bill_type = 'EDU_FEE'
  AND status in ('issued')
GROUP BY payment_key, student_id, bill_id

SELECT count(*)
FROM erp_payment_manual
where student_id = #{studentId}
  AND payment_key = #{paymentKey}
  AND yy = #{yy}
  AND mm = #{mm}

SELECT status
from erp_payment_bill
WHERE payment_key = #{paymentKey}
  AND student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
  AND status NOT IN ('destroyed')
  AND bill_type = 'BOOK_FEE'

SELECT *
from erp_payment_config
WHERE center_code = #{centerCode}

SELECT *
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{year}
  AND mm = #{month}

SELECT s.student_id AS studentId, s.student_name AS studentName, (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last) AS parentPhone, p.payment_key AS paymentKey, SUM(pd.amount) AS amount FROM erp_student s JOIN erp_parent pa ON pa.student_id = s.student_id JOIN erp_payment p ON p.student_id = s.student_id JOIN erp_payment_detail pd ON pd.payment_key = p.payment_key WHERE (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last) IN
#{phone}
AND p.yy = #{yy} AND p.mm = #{mm} AND pd.item_type = #{type} GROUP BY s.student_id, s.student_name, (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last), p.payment_key

SELECT s.student_id AS studentId, s.student_name AS studentName, (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last) AS parentPhone, p.payment_key AS paymentKey, SUM(pd.amount) AS amount
FROM erp_student s JOIN erp_parent pa ON pa.student_id = s.student_id JOIN erp_payment p ON p.student_id = s.student_id JOIN erp_payment_detail pd ON pd.payment_key = p.payment_key
WHERE s.student_id IN
#{studentId}
AND p.yy = #{yy} AND p.mm = #{mm} AND pd.item_type = #{type}
GROUP BY s.student_id, s.student_name, (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last), p.payment_key

SELECT bill_id AS billId
FROM erp_payment_bill
WHERE payment_key = #{paymentKey}
  AND status = 'issued'
  AND bill_type = #{type}

SELECT COUNT(*)
FROM erp_payment_bill
WHERE student_id IN

    #{id}

AND yy = #{yy}
AND mm = #{mm}
AND bill_type = #{billType}
AND status NOT IN ('destroyed', 'canceled')

SELECT fee
FROM ERP_CLASS_FEE_MAP
WHERE class_key = #{classKey}
  AND center_code = #{centerCode}

SELECT TOP 1 payment_key
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
ORDER BY created_at DESC

SELECT *
from erp_payment
where payment_key = #{paymentKey}

SELECT *
FROM erp_payment_bill
WHERE bill_id = #{billId}

SELECT s.student_id AS studentId, (p.yy + '-' + p.mm) AS classDate, s.student_name AS studentName, p.payment_key AS paymentKey,
STUFF(( SELECT ', ' + sub.class_name FROM ( SELECT DISTINCT cc2.class_name, cc2.class_type FROM erp_time_table_assign ta2 JOIN erp_time_table t2 ON ta2.time_table_key = t2.time_table_key JOIN erp_class_code cc2 ON cc2.class_key = CASE WHEN t2.class_key = 'COM' THEN ta2.class_key ELSE t2.class_key END WHERE ta2.student_id = p.student_id AND t2.yy = p.yy AND t2.mm = p.mm) AS sub ORDER BY sub.class_type FOR XML PATH (''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS subject, hu.user_name AS hanTeacher, bu.user_name AS bookTeacher, p.amount AS amount, p.status, p.paid_date AS paidDate, edu.han_material_fee AS hanMaterialFee, edu.book_material_fee AS booKMaterialFee, edu.han_edu_fee AS hanFee, edu.book_edu_fee AS bookFee
FROM erp_payment p LEFT JOIN ( SELECT pd.payment_key, -- 교육비 MAX(CASE WHEN pd.item_type = 'EDU_FEE' AND pd.class_type = '1' THEN pd.amount END) AS han_edu_fee, MAX(CASE WHEN pd.item_type = 'EDU_FEE' AND pd.class_type = '2' THEN pd.amount END) AS book_edu_fee, -- 교재비 MAX(CASE WHEN pd.item_type = 'BOOK_FEE' AND pd.class_type = '1' THEN pd.amount END) AS han_material_fee, MAX(CASE WHEN pd.item_type = 'BOOK_FEE' AND pd.class_type = '2' THEN pd.amount END) AS book_material_fee
FROM erp_payment_detail pd GROUP BY pd.payment_key) AS edu ON p.payment_key = edu.payment_key JOIN erp_student s ON p.student_id = s.student_id JOIN erp_teacher_assign ta ON s.student_id = ta.student_id LEFT JOIN erp_user hu ON ta.assign_han_teacher = hu.user_code LEFT JOIN erp_user bu ON ta.assign_book_teacher = bu.user_code WHERE s.center_code = #{centerCode}
AND p.student_id = #{studentId}
ORDER BY classDate DESC;

SELECT TOP ${count} * FROM (select p.bill_id AS billId, (p.yy + '-' + p.mm) AS inym, 'S' AS gb, p.approved_date AS indate, p.han_amount AS inmoney, CASE WHEN p.product_name = '교육비' THEN 'S' WHEN p.product_name = '교재비' THEN 'B' ELSE null END AS gubun, p.created_at from erp_payment p WHERE p.han_amount IS NOT NULL AND p.student_id = #{studentId} AND P.approved_date IS NOT NULL
UNION ALL
select p.bill_id AS billId, (p.yy + '-' + p.mm) AS inym, 'I' AS gb, p.approved_date AS indate, p.book_amount AS inmoney, CASE WHEN p.product_name = '교육비' THEN 'S' WHEN p.product_name = '교재비' THEN 'B' ELSE null END AS gubun, p.created_at from erp_payment p WHERE p.book_amount IS NOT NULL AND p.student_id = #{studentId}) AS combined AND P.approved_date IS NOT NULL ORDER BY combined.billId ASC;

SELECT payment_key
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{year}
  AND mm = #{month}

SELECT p.payment_key
FROM erp_payment p
         JOIN erp_payment_detail pd ON p.payment_key = pd.payment_key
WHERE p.student_id = #{studentId}
  AND pd.time_table_key = #{timeTableKey}
GROUP BY p.payment_key

