mapper.update:
UPDATE erp_payment_detail
SET amount =
        CASE
            -- 교육비
            WHEN item_type = 'EDU_FEE' AND class_type = '1' THEN #{hanEduFee}
            WHEN item_type = 'EDU_FEE' AND class_type = '2' THEN #{bookEduFee}

            -- 교재비
            WHEN item_type = 'BOOK_FEE' AND class_type = '1' THEN #{hanMaterialFee}
            WHEN item_type = 'BOOK_FEE' AND class_type = '2' THEN #{bookMaterialFee}
            END
WHERE payment_key = #{paymentKey}
  AND item_type IN ('EDU_FEE', 'BOOK_FEE');

