UPDATE erp_payment
SET amount        = #{amount},
    unpaid_amount = #{unpaidAmount}
where payment_key = #{paymentKey}

UPDATE erp_teacher_assign
set han_material_fee  = #{hanMaterialFee},
    book_material_fee = #{bookMaterialFee}
where student_id = #{studentId}
